using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;

namespace Warehouse.Tests;

[TestClass]
public sealed class ApiTests
{
    private sealed class Factory : WebApplicationFactory<Program>
    {
        public readonly string Db = Path.Combine(Path.GetTempPath(), $"wh-{Guid.NewGuid():N}.db");
        protected override void ConfigureWebHost(IWebHostBuilder b)
        {
            b.UseSetting("ConnectionStrings:Warehouse", $"Data Source={Db}");
        }
        protected override void Dispose(bool disposing)
        {
            base.Dispose(disposing);
            Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();
            try { File.Delete(Db); } catch { }
        }
    }

    private static async Task<JsonElement> Json(HttpResponseMessage r) =>
        (await r.Content.ReadFromJsonAsync<JsonElement>());

    private static async Task<string> NewSupplier(HttpClient c, string name = "Acme")
    {
        var r = await c.PostAsJsonAsync("/suppliers", new { name, email = "a@b.c" });
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode);
        return (await Json(r)).GetProperty("id").GetString()!;
    }

    private static object Prod(string sup, string sku = "S1", int stock = 5, int level = 2, int status = 0) =>
        new { sku, name = "Widget", stock, reorderLevel = level, status, supplierId = sup };

    [TestMethod]
    public async Task SupplierRoundTrip()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var id = await NewSupplier(c);
        var r = await c.PutAsJsonAsync($"/suppliers/{id}", new { name = "Acme2" });
        Assert.AreEqual(HttpStatusCode.OK, r.StatusCode);
        Assert.AreEqual("Acme2", (await Json(r)).GetProperty("name").GetString());
        Assert.AreEqual(1, (await Json(await c.GetAsync("/suppliers"))).GetArrayLength());
        Assert.AreEqual(HttpStatusCode.NoContent, (await c.DeleteAsync($"/suppliers/{id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await c.GetAsync($"/suppliers/{id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await c.GetAsync($"/suppliers/{Guid.NewGuid()}")).StatusCode);
    }

    [TestMethod]
    public async Task ProductRoundTripAndSupplierProducts()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sup = await NewSupplier(c);
        var r = await c.PostAsJsonAsync("/products", Prod(sup));
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode);
        var p = await Json(r);
        var id = p.GetProperty("id").GetString();
        Assert.AreEqual(sup, p.GetProperty("supplierId").GetString());
        Assert.AreEqual(0, p.GetProperty("status").GetInt32());
        Assert.IsFalse(p.GetProperty("needsReorder").GetBoolean());

        var u = await c.PutAsJsonAsync($"/products/{id}", Prod(sup, stock: 1));
        Assert.AreEqual(HttpStatusCode.OK, u.StatusCode);
        Assert.IsTrue((await Json(u)).GetProperty("needsReorder").GetBoolean());

        var s = await Json(await c.GetAsync($"/suppliers/{sup}"));
        Assert.AreEqual(1, s.GetProperty("products").GetArrayLength());

        Assert.AreEqual(HttpStatusCode.OK, (await c.GetAsync($"/products/{id}")).StatusCode);
        Assert.AreEqual(1, (await Json(await c.GetAsync("/products"))).GetArrayLength());
        Assert.AreEqual(HttpStatusCode.NoContent, (await c.DeleteAsync($"/products/{id}")).StatusCode);
    }

    [TestMethod]
    public async Task NeedsReorderRules()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sup = await NewSupplier(c);
        async Task<bool> Check(string sku, int stock, int level, int status) =>
            (await Json(await c.PostAsJsonAsync("/products", Prod(sup, sku, stock, level, status)))).GetProperty("needsReorder").GetBoolean();
        Assert.IsTrue(await Check("A", 2, 2, 0));
        Assert.IsFalse(await Check("B", 3, 2, 0));
        Assert.IsFalse(await Check("C", 0, 2, 1));
    }

    [TestMethod]
    public async Task ValidationErrors()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sup = await NewSupplier(c);
        foreach (var body in new object[]
        {
            Prod(sup, stock: -1), Prod(sup, level: -1), Prod(sup, status: 7),
            Prod(Guid.NewGuid().ToString()), Prod(sup, sku: new string('x', 21)),
            Prod(sup, sku: ""),
        })
            Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/products", body)).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/suppliers", new { name = "" })).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/suppliers", new { name = new string('x', 101) })).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/suppliers", new { name = "n", email = new string('x', 101) })).StatusCode);
    }

    [TestMethod]
    public async Task UniqueConflicts()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sup = await NewSupplier(c);
        Assert.AreEqual(HttpStatusCode.Conflict, (await c.PostAsJsonAsync("/suppliers", new { name = "Acme" })).StatusCode);
        Assert.AreEqual(HttpStatusCode.Created, (await c.PostAsJsonAsync("/products", Prod(sup))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Conflict, (await c.PostAsJsonAsync("/products", Prod(sup))).StatusCode);
    }
}
EOF
